const listAccounts = `-- name: ListAccounts :many
SELECT id, name, institution, type, currency, iban, is_active, created_at, user_id, tax_treatment, employer_match_pct, import_security_isin FROM accounts WHERE is_active = true ORDER BY name
`

func (q *Queries) ListAccounts(ctx context.Context) ([]Account, error) {
	rows, err := q.db.Query(ctx, listAccounts)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Account{}
	for rows.Next() {
		var i Account
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Institution,
			&i.Type,
			&i.Currency,
			&i.IBAN,
			&i.IsActive,
			&i.CreatedAt,
			&i.UserID,
			&i.TaxTreatment,
			&i.EmployerMatchPct,
			&i.ImportSecurityISIN,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

